<?php
declare(strict_types=1);
require __DIR__.'/shipping.php';
use Shipping\{Fulfilment,Ledger,Rules};
$settings=clone $s;$settings->providers['goods']='helics';$settings->federationId='cancel-test';$settings->peers['goods']=['source'=>'storage','endpoint'=>'storage/events'];$shipping=new Fulfilment($db,$settings);$ledger=new Ledger($db,$settings);
function cancelDrain():void {global $db,$ledger;$r=$ledger->status()['run'];$db->transaction(fn($u)=>$u->execute('UPDATE boundary_outbox SET sent_at=clock_timestamp() WHERE run_id=?',[$r['id']]));shippingDrain();}
$c=shippingSubmit(['action'=>'create','customer'=>'RACE','destination'=>'CUSTOMER-A','lines'=>[['sku'=>'PRODUCT','quantity'=>1]]]);cancelDrain();shippingSubmit(['action'=>'fulfil','reference'=>$c['id']]);cancelDrain();
shippingSubmit(['action'=>'cancel','reference'=>$c['id']]);cancelDrain();$o=$shipping->order($c['id']);shippingCheck($o['status']==='cancelling','cancellation waits for outstanding reservation outcome');
$i=$o['intents'][0];$r=$ledger->status()['run'];
$e=['schema_version'=>'1.0','type'=>'shipping.fact.v1','event_id'=>Rules::uuid4(),'federation_id'=>'cancel-test','run_id'=>$r['id'],'epoch'=>$r['epoch'],'correlation_id'=>$o['correlation_id'],'causation_id'=>$i['id'],'aggregate_id'=>$o['id'],'aggregate_version'=>1,'source'=>'storage','destination'=>'shipping','boundary'=>'goods','effective_time'=>$r['granted']+1,'quantity_unit'=>'item','payload'=>['intent_id'=>$i['id'],'owner'=>'storage','result'=>'reserved','reference'=>$o['id'],'destination'=>$o['destination'],'sku'=>'PRODUCT','quantity'=>1]];
$shipping->ingest($e,'storage/events');cancelDrain();$o=$shipping->order($o['id']);shippingCheck($o['status']==='cancelling'&&$o['lines'][0]['reserved']===1,'late reservation creates compensation instead of disappearing');
$release=array_values(array_filter($o['intents'],fn($row)=>$row['kind']==='release'))[0];$r=$ledger->status()['run'];$e['event_id']=Rules::uuid4();$e['causation_id']=$release['id'];$e['effective_time']=$r['granted']+1;$e['payload']['intent_id']=$release['id'];$e['payload']['result']='released';$shipping->ingest($e,'storage/events');cancelDrain();$o=$shipping->order($o['id']);shippingCheck($o['status']==='cancelled'&&$o['lines'][0]['reserved']===0,'cancel completes only after durable release confirmation');
shippingCheck(count(array_filter($o['intents'],fn($i)=>in_array($i['kind'],['pick','transfer'],true)))===0,'cancelling order never starts irreversible work');
shippingCheck($shipping->ingest($e,'storage/events')==='duplicate','compensation confirmation redelivery deduplicates');
echo "Shipping cancellation compensation checks passed\n";
$c=shippingSubmit(['action'=>'create','customer'=>'FAILED-COMPENSATION','destination'=>'CUSTOMER-A','lines'=>[['sku'=>'PRODUCT','quantity'=>1],['sku'=>'WIDGET','quantity'=>1]]]);cancelDrain();shippingSubmit(['action'=>'fulfil','reference'=>$c['id']]);cancelDrain();$o=$shipping->order($c['id']);$reserves=array_values(array_filter($o['intents'],fn($i)=>$i['kind']==='reserve'));
function cancellationReply(array $o,array $i,string $result):array {global $ledger;$r=$ledger->status()['run'];foreach($o['lines'] as $l)if($l['id']===$i['line_id'])$line=$l;return ['schema_version'=>'1.0','type'=>'shipping.fact.v1','event_id'=>Shipping\Rules::uuid4(),'federation_id'=>'cancel-test','run_id'=>$r['id'],'epoch'=>$r['epoch'],'correlation_id'=>$o['correlation_id'],'causation_id'=>$i['id'],'aggregate_id'=>$o['id'],'aggregate_version'=>1,'source'=>'storage','destination'=>'shipping','boundary'=>'goods','effective_time'=>$r['granted']+1,'quantity_unit'=>'item','payload'=>['intent_id'=>$i['id'],'owner'=>'storage','result'=>$result,'reference'=>$o['id'],'sku'=>$line['sku'],'quantity'=>$line['quantity'],'destination'=>$o['destination']]];}
$shipping->ingest(cancellationReply($o,$reserves[0],'reserved'),'storage/events');cancelDrain();shippingSubmit(['action'=>'cancel','reference'=>$o['id']]);cancelDrain();$o=$shipping->order($o['id']);$release=array_values(array_filter($o['intents'],fn($i)=>$i['kind']==='release'))[0];$shipping->ingest(cancellationReply($o,$release,'failed'),'storage/events');cancelDrain();$shipping->ingest(cancellationReply($o,$reserves[1],'reserved'),'storage/events');cancelDrain();$o=$shipping->order($o['id']);shippingCheck(count(array_filter($o['intents'],fn($i)=>in_array($i['kind'],['pick','transfer'],true)))===0,'failed compensation cannot restart picking after a late reservation');
